-- Uvoz 31 pregledanih treningov lanske sezone (2026-01-01 do 2026-02-28). Vse ali nič. Zgenerirano s treningi_uvoz/sql_uvoz_2025.js.
DO $do$
DECLARE
  o uuid := (SELECT id FROM public.trainers WHERE email = 'uros.jedlovcnik@gmail.com' LIMIT 1);
  note text := 'Uvoz iz zvezka 2025/26 (2026-01-01–2026-02-28)';
  n int; s bigint; l int; k int;
BEGIN
  CREATE TEMP TABLE _t ON COMMIT DROP AS
  SELECT (x->>'d')::date AS d, string_to_array(regexp_replace(x->>'l', '(.)(?=.)', '\1,', 'g'), ',') AS lv,
         CASE WHEN (x->>'o') = '1' THEN 'glavna_takoj' ELSE 'obicajni' END AS ord, (x->>'m')::int AS m, (x->>'e')::int AS e, x->'i' AS items
  FROM jsonb_array_elements($j$[{"d":"2026-01-07","l":"C","o":0,"m":1400,"e":28,"i":[["R","200 RAZP",200],["O","4x50 25 PD + 25 H",200],["V","8x25 KN Z DESKO 1x GV 1x GN",200],["V","6x25 KV RRU",150],["M","50 RAZP",50],["V","8x25 PL DN 1x OT 1x RS",200],["V","8x25 PL DZ ↑DESNA ↓LEVA",200],["G","200 POLJUBNO",200]]},{"d":"2026-01-07","l":"A","o":0,"m":2300,"e":33,"i":[["R","300 RAZP",300],["O","8x50 M 25 N + 25 CT",400],["V","4x100 PL K 1x 1. 25 D 1x 2. 25 D 1x 3. 25 D 1x 4. 25 D",400],["V","6x50 PL N 25 HITRO + 25 RAZP",300],["M","50 RAZP",50],["G","3x100 VL\n3x75 M\n25 M RAZP\n3x50 TEMPO\n3x25 D\n25 RAZP",800],["K","50 RAZP",50]]},{"d":"2026-01-08","l":"AB","o":0,"m":2400,"e":34,"i":[["R","300 RAZP",300],["O","8x50 MM",400],["V","2x( 8x25 PL ) 1x ↑DN PR ↓SHARK 1x ↑VRTAVKA ↓RRU PESTI",400],["G","2x( 4x50 KVL ) 1x @1' 1x @50\"\n2x( 2x100 M ) 1x NORMALNO 1x OBRATNO\n2x200 K @3'30\"",1200],["K","100 RAZP",100]]},{"d":"2026-01-12","l":"AB","o":0,"m":2200,"e":31,"i":[["R","300 RAZP",300],["O","3x150 MBK PO 50 25 V + 25 CT",450],["G","3x50 STOP 1-3 @1'",150],["M","50 RAZP",50],["G","3x100 M p20\"\n3x25 STOP 1-3 @40\"\n25 RAZP\n10x75 KVL T",1150],["K","100 RAZP",100]]},{"d":"2026-01-14","l":"C","o":0,"m":1450,"e":29,"i":[["R","200 RAZP",200],["O","4x50 25 H RRU OT + 25 PD",200],["V","8x25 PL KN Z DESKO VDIH 3-5s",200],["V","6x25 PL KV RRU 3s",150],["M","50 RAZP",50],["V","4x50 ↑PD 5s ↓P 1-1",200],["V","8x25 PN Z DESKO 1x 1-3 1x 1-1",200],["G","2x100 P OBRATI PODVODNI",200],["K","50 RAZP",50]]},{"d":"2026-01-14","l":"A","o":0,"m":2300,"e":33,"i":[["R","300 RAZP",300],["O","2x( 100 K / 75 P / 50 H / 25 D ) 1. 25 N + 25 CT 2. 25 V + 25 CT",500],["V","8x25 PL 1x DN PV 1x DN PR",200],["V","4x50 PL KV 1x RRU PESTI 1x RRU PZDZ",200],["M","50 RAZP",50],["G","5x( 100 KVL / 50 K T / 25 STIL HITRO / 25 RAZP )",1000],["K","50 RAZP",50]]},{"d":"2026-01-15","l":"AB","o":1,"m":2300,"e":33,"i":[["R","300 RAZP",300],["O","6x75 MBK PO 75 25 N + 25 V + 25 CT",450],["G","4x( 4x50 ) 1x @1'15\" 1x @1'10\" 1x @1' 1x @50\" T 35",800,"4X(4X50) 1X @1'15\" 1X @1'10\" 1X @1' 1X @50\" T"],["M","50 RAZP",50],["V","4x50 PL N 25 MAX + 25 RAZP",200],["V","6x75 PL 25 KBD + 25 VATERPOLO + 25 ČMZ",450],["K","50 RAZP",50]]},{"d":"2026-01-19","l":"AB","o":0,"m":2400,"e":34,"i":[["R","300 RAZP",300],["O","6x75 50 MBD + 25 D",450],["V","4x50 PL H RRU ↑Z ↓90°",200],["V","10x50 PL 4-3-2-1 @1' T 40-36-32-28",500,"10X50 PL 4-3-2-1 @1' T"],["M","50 RAZP",50],["G","6x100 KVL @2' T 1:15\n200 KN",800,"6X100 KVL @2' T\n200 KN"],["K","100 RAZP",100]]},{"d":"2026-01-22","l":"AB","o":0,"m":2300,"e":33,"i":[["R","300 RAZP",300],["O","4x100 1x 75 K + 25 H 1x 75 K + 25 D",400],["V","6x50 PL K VSAKIČ 10m PV",300],["V","4x50 PL ↑15m PV + D 2-2-2 ↓15m PV + K ČIM POČASNEJE",200],["M","50 RAZP",50],["G","2x( 3x100 / 50 ) 1x @2' 1x @1'45\" T 1:10-1:14\n10x25 ROKE VL",950,"2X(3X100 / 50) 1X @2' 1X @1'45\" T\n10X25 ROKE VL"],["K","100 RAZP",100]]},{"d":"2026-01-21","l":"C","o":0,"m":1450,"e":29,"i":[["R","200 RAZP",200],["O","4x50 25 PPV + 25 PD",200],["V","6x25 PL HN ROTACIJA",150],["V","4x25 PL HN LONČEK",100],["V","6x25 PL HV RRU OT + LONČEK",150],["V","6x25 H CT LONČEK",150],["M","50 RAZP",50],["G","4x75 50 P + 25 K\n2x50 25 P! + 25 RAZP",400],["K","50 RAZP",50]]},{"d":"2026-01-21","l":"A","o":0,"m":2250,"e":32,"i":[["R","300 RAZP",300],["O","6x75 25 MBK + 50 K",450],["V","4x50 PL 25 N MAX + 25 H",200],["M","50 RAZP",50],["G","3x( 6x50 @1' ) 2x EASY 1x HITRO 1x PL 1x VL 1x NORMALNO",900],["M","100 RAZP",100],["V","4x50 25 PPV + 25 H",200],["K","50 RAZP",50]]},{"d":"2026-01-26","l":"AB","o":0,"m":2150,"e":30,"i":[["R","300 RAZP",300],["O","4x100 M PO 25 Z ZAMIKOM",400],["V","4x50 PL 1x SUPERMAN 1x KZ DIH KONTRA",200],["V","8x25 PL 1x PV HN 1x VATERPOLO",200],["M","50 RAZP",50],["G","4x( 100 @2' / 50 p45\" )",600],["M","50 RAZP",50],["G","4x75 50 N + 25 MAX",300],["K","50 RAZP",50]]},{"d":"2026-01-29","l":"AB","o":0,"m":2300,"e":33,"i":[["R","300 RAZP",300],["O","4x100 PL 25 N + 75 CT 1x H 1x K",400],["V","10x25 PL ↑D CT ↓SCULLING",250],["V","4x50 K RRU 1x PPDZ 1x PESTI",200],["M","50 RAZP",50],["G","2x( 6x50 @1' ) 1x MAD 1x NORMALNO",600],["M","50 RAZP",50],["G","8x50 25! + 25 RAZP 1x N 1x K 1x N 1x STIL",400],["K","50 RAZP",50]]},{"d":"2026-01-28","l":"C","o":0,"m":1450,"e":29,"i":[["R","200 RAZP",200],["O","4x75 P 1-2/1-3/PD",300],["V","8x25 PL KN 1x PR 1x GV",200],["V","6x25 PL K RRU 2s",150],["V","6x25 PL K RRU PALEC",150],["V","3x50 PL K CT",150],["M","50 RAZP",50],["G","200 P",200],["K","50 RAZP",50]]},{"d":"2026-01-28","l":"A","o":0,"m":2250,"e":32,"i":[["R","300 RAZP",300],["O","4x50 PL ↑D 5-2 ↓PR KN",200],["V","4x75 PL K VSAKIH 25 1 CIKEL MANJ",300],["M","50 RAZP",50],["G","3x100 KVL @2'\n3x50 K 1-3\n2x100 PL @2'\n2x50 NOGE PL @1'\n100 M\n50 MAX",900],["M","50 RAZP",50],["V","8x50 1x KZ ↑LEVA ↓DESNA DIH KONTRA 1x DIH 3/5",400],["K","50 RAZP",50]]},{"d":"2026-02-02","l":"AB","o":0,"m":2450,"e":35,"i":[["R","300 RAZP",300],["O","8x50 MM",400],["V","4x75 PL KN 25 GV + 25 GN + 25!",300],["V","12x25 PL VSAKIH 2 1 CIKEL MANJ",300],["M","50 RAZP",50],["G","16x50 4x 3+1 4x 2+2 4x VL 3+1 4x VL 2+2",800],["M","50 RAZP",50],["V","8x25 ↑PPV ↓GERMANJA KN",200],["K","50 RAZP",50]]},{"d":"2026-02-05","l":"AB","o":0,"m":2200,"e":31,"i":[["R","300 RAZP",300],["O","2x( 100 K / 75 H / 50 P / 25 D )",500],["V","4x50 PL ↑HN RZ ↓H 6-3-6",200],["V","10x25 PL ↑HITLER ↓RRU 90°",250],["M","50 RAZP",50],["G","1x( 50 / 100 / 200 / 100 / 50 )\n1x( 25 / 50 / 100 / 50 / 25 )\n50 RAZP",800],["K","100 RAZP",100]]},{"d":"2026-02-04","l":"C","o":0,"m":1450,"e":29,"i":[["R","200 RAZP",200],["O","2x100 75 P + 25 K",200],["V","8x25 PL DN BOK/T/H",200],["V","6x25 PL DV ↑LEVA ↓DESNA",150],["V","6x25 PL DV 2-2",150],["V","6x25 PL HV 6-3-6",150],["M","50 RAZP",50],["G","3x100 75 P + 25 H",300],["K","50 RAZP",50]]},{"d":"2026-02-04","l":"A","o":0,"m":2250,"e":32,"i":[["R","300 RAZP",300],["O","3x100 MBD 50 N + 25 V + 25 CT",300],["V","8x25 PL KN RV 90°",200],["V","4x50 PL 1x 6-3-6 1x SHARK 1",200],["M","50 RAZP",50],["G","8x100 2x VL 2x 75 K + 25 D 2x 50 K! + 50 H 2x 25 D + 75 K",800],["M","50 RAZP",50],["G","6x50 25! + 25 RAZP",300],["K","50 RAZP",50]]},{"d":"2026-02-09","l":"AB","o":1,"m":2250,"e":32,"i":[["R","300 RAZP",300],["O","4x100 M",400],["G","3x100 KVL\n2x100 K T\n100 K HITRO!",600],["M","50 RAZP",50],["V","8x25 KV PACMAN",200],["V","6x50 PL KV ŠPRICANJE + POUDAREK PDZ",300],["V","6x50 PL MAX OBRAT",300],["K","100 RAZP",100]]},{"d":"2026-02-12","l":"AB","o":0,"m":2300,"e":33,"i":[["R","300 RAZP",300],["O","8x50 M 25 N + 25 CT",400],["V","6x50 PL ↑DN PV ↓DV 3-3",300],["V","10x25 PL ↑VRTAVKA ↓KBD",250],["M","50 RAZP",50],["G","6x100 3x EASY 2x TEMPO 1x HITRO",600],["M","50 RAZP",50],["G","5x50 2x TEMPO 2x HITRO 1x MAX",250],["K","100 RAZP",100]]},{"d":"2026-02-11","l":"C","o":0,"m":1600,"e":32,"i":[["R","200 RAZP",200],["O","6x50 25 P 1-1 + 25 K/H",300],["V","4x50 PL KN SUPERMAN",200],["V","6x25 PL KZ",150],["V","6x25 PL K RRU ZADRGA",150],["V","4x50 PL ↑K ↓HN",200],["M","50 RAZP",50],["G","3x100 P PODVODNI",300],["K","50 RAZP",50]]},{"d":"2026-02-11","l":"A","o":0,"m":2150,"e":30,"i":[["R","300 RAZP",300],["O","6x50 ↑MBP ↓P",300],["V","8x25 PL ↑PR KN ↓KN DR",200],["V","4x50 PL VSAKIČ 10m PV + K RRU PALEC",200],["M","50 RAZP",50],["G","4x50 K @1'\n4x100 VL @2'\n4x50 K @50\"",800],["M","50 RAZP",50],["Z","8x25 ↑STIL MAX ↓H",200],["K","50 RAZP",50]]},{"d":"2026-02-16","l":"AB","o":0,"m":2400,"e":34,"i":[["R","300 RAZP",300],["O","6x75 25 MBK + 50 K",450],["V","8x50 PL 1x DN 1x DN KR 2x 25 D + 25 H",400],["V","4x50 PL ↑KV 2-2 ↓RRU STEGR",200],["M","50 RAZP",50],["G","3x( 6x50 ) 1x @1' 1x @55\" 1x @50\"",900],["K","100 RAZP",100]]},{"d":"2026-02-19","l":"AB","o":0,"m":2200,"e":31,"i":[["R","300 RAZP",300],["O","3x100 MBD 50 N + 25 V + 25 CT",300],["V","4x50 PL SALTO NA POL ŠPRINT DO KONCA",200],["V","8x25 PL ↑VATERPOLO ↓RRU 3s",200],["M","50 RAZP",50],["G","8x50 VL\n6x50 MBK\n4x50 TEMPO\n2x( 50 MAX / 50 RAZP )",1100],["K","50 RAZP",50]]},{"d":"2026-02-18","l":"C","o":0,"m":1450,"e":29,"i":[["R","200 RAZP",200],["O","3x100 25 K + 50 P + 25 H",300],["V","4x50 PL HN RZ",200],["V","4x50 PL HZ ↑DESNA ↓LEVA",200],["V","6x25 H CT",150],["M","50 RAZP",50],["G","10x25 P 1x HITRO PODVODNI 1x POČASI",250],["K","100 RAZP",100]]},{"d":"2026-02-18","l":"A","o":0,"m":2250,"e":32,"i":[["R","300 RAZP",300],["O","8x50 MM",400],["V","12x25 PL ↑SCULLING ↓H RRU Z",300],["V","4x50 PL 25 K + 25 KBD",200],["M","50 RAZP",50],["G","4x( 100 T / 25 MAX / 25 RAZP )",600],["M","50 RAZP",50],["V","10x25 V ML PR",250],["K","100 RAZP",100]]},{"d":"2026-02-23","l":"AB","o":1,"m":2300,"e":33,"i":[["R","300 RAZP",300],["O","8x50 M OBRATNO",400],["G","3x100 VL @2'\n6x50 @55\"\n3x100 @1'45\"",900],["M","50 RAZP",50],["V","4x50 PL KZ DIH KONTRA",200],["V","8x25 PL 10m PV + K ČIM POČASNEJE",200],["Z","4x50 PL ↑MAX ↓RAZP",200],["K","50 RAZP",50]]},{"d":"2026-02-26","l":"AB","o":0,"m":2300,"e":33,"i":[["R","300 RAZP",300],["O","100 K + 75 P + 50 H + 25 D + 25 D + 50 H + 75 P + 100 K",500],["V","4x50 PL SALTO NA POL ŠPRINT",200],["V","8x25 PL 10m PV KBD",200],["M","50 RAZP",50],["G","1x( 25 D / 50 T / 75 MBD / 100 HITRO / 200 VL / 100 HITRO / 75 MBD / 50 T / 25 D )",700],["M","50 RAZP",50],["G","4x50 K 1x 15m D 1x 25m D 1x 35m D 1x 50m D @1'",200],["K","100 RAZP",100]]},{"d":"2026-02-25","l":"C","o":0,"m":1500,"e":30,"i":[["R","200 RAZP",200],["O","6x50 ↑P ↓H/K",300],["V","8x25 PL 1x KN 1x HN",200],["V","4x50 PL ↑KV 1-1 ↓6-3-6",200],["V","8x25 K CT 4x PL 4x BREZ",200],["M","50 RAZP",50],["V","4x50 1x P 1-1-1 1x P 2-1",200],["V","4x25 PPV",100],["K","50 RAZP",50]]},{"d":"2026-02-25","l":"A","o":0,"m":2400,"e":34,"i":[["R","300 RAZP",300],["O","3x150 PL 50 N + 50 V + 50 CT",450],["V","10x25 PL 1x DN KR 1x KV 1-1",250],["M","50 RAZP",50],["G","4x100 M PO 25\n4x75 STOP PO 25\n4x50 TEMPO @55\"\n4x25 D",1000],["M","50 RAZP",50],["Z","10x25 V ML PR",250],["K","50 RAZP",50]]}]$j$::jsonb) x;

  IF EXISTS (SELECT 1 FROM _t JOIN public.trainings t ON t.trainer_id = o AND t.date = _t.d AND t.levels = _t.lv) THEN
    RAISE EXCEPTION 'Kateri od treningov je že v bazi';
  END IF;

  CREATE TEMP TABLE _i ON COMMIT DROP AS
  SELECT _t.d, _t.lv, (i.ord - 1)::int AS pos,
         CASE i.v->>0 WHEN 'R' THEN 'razplavanje' WHEN 'O' THEN 'ogrevalna' WHEN 'V' THEN 'vaje' WHEN 'M' THEN 'vmesno_razplavanje'
                      WHEN 'G' THEN 'glavna' WHEN 'Z' THEN 'zakljucek' WHEN 'K' THEN 'zakljucno_razplavanje' END AS phase,
         i.v->>1 AS txt, (i.v->>2)::int AS m,
         coalesce(i.v->>3, replace(replace(upper(i.v->>1), '( ', '('), ' )', ')')) AS fp, i.v->>4 AS b
  FROM _t CROSS JOIN LATERAL jsonb_array_elements(_t.items) WITH ORDINALITY AS i(v, ord);

  INSERT INTO public.training_sets AS ts (trainer_id, phase, levels, text, structure, meters, fingerprint, source, notes)
  SELECT o, phase, (SELECT array_agg(DISTINCT u ORDER BY u) FROM _i j, unnest(j.lv) u WHERE j.phase = i.phase AND j.fp = i.fp),
         min(txt), jsonb_build_object('v', 1, 'meters', min(m)), min(m), fp, 'uvoz', 'zvezek 2025/26'
  FROM _i i WHERE phase IN ('ogrevalna', 'vaje', 'glavna', 'zakljucek') GROUP BY phase, fp
  ON CONFLICT (trainer_id, phase, fingerprint) DO UPDATE
    SET levels = (SELECT array_agg(DISTINCT u ORDER BY u) FROM unnest(ts.levels || excluded.levels) u);
  GET DIAGNOSTICS k = ROW_COUNT;
  IF k <> 142 THEN RAISE EXCEPTION 'Serije: %', k; END IF;

  INSERT INTO public.trainings (trainer_id, term_id, date, levels, status, order_variant, total_meters, estimated_minutes, notes)
  SELECT o, (SELECT te.id FROM public.terms te JOIN public.trainer_terms tt ON tt.term_id = te.id
              WHERE tt.trainer_id = o AND te.day = extract(isodow FROM _t.d)::int
                AND _t.d BETWEEN coalesce(te.date_from, _t.d) AND coalesce(te.date_to, _t.d) LIMIT 1),
         _t.d, _t.lv, 'izveden', _t.ord, _t.m, _t.e, note
  FROM _t;

  INSERT INTO public.training_items (training_id, position, phase, set_id, text, structure, meters, fingerprint, level_variants)
  SELECT t.id, i.pos, i.phase,
         (SELECT x.id FROM public.training_sets x WHERE x.trainer_id = o AND x.phase = i.phase AND x.fingerprint = i.fp),
         i.txt, jsonb_build_object('v', 1, 'meters', i.m), i.m, i.fp,
         CASE WHEN i.b IS NULL THEN '{}'::jsonb ELSE jsonb_build_object('B', jsonb_build_object('text', i.b)) END
  FROM _i i JOIN public.trainings t ON t.trainer_id = o AND t.date = i.d AND t.levels = i.lv AND t.notes = note;

  SELECT count(DISTINCT t.id), count(i.id), sum(i.meters), count(i.set_id) INTO n, k, s, l
  FROM public.trainings t JOIN public.training_items i ON i.training_id = t.id WHERE t.trainer_id = o AND t.notes = note;
  IF n <> 31 OR k <> 249 OR s <> 64350 OR l <> 147 THEN
    RAISE EXCEPTION 'Kontrola: treningov %, postavk %, metrov %, povezanih %', n, k, s, l;
  END IF;
END $do$;
